// Structured Output Parsers upstream already enforce schema on the
// happy path; this stays defensive in case a parser retry still
// fails, and separates real fetch/summarize failures (stubs) from
// valid summaries so we can report exactly which sources failed.
const items = $input.all();
const summaries = [];
const sourcesSucceeded = [];
const sourcesFailed = [];
const ALL_SOURCES = ["TechCabal", "Business Daily", "The Star", "Standard", "Kenyan WallStreet"];

for (const item of items) {
  const j = item.json;

  // Failure stub from the IF-gate branch
  if (j && j.status === 'fetch_failed') {
    sourcesFailed.push(j.source);
    continue;
  }

  let raw = j.output ?? j.text ?? j;

  if (typeof raw === 'string') {
    raw = raw
      .trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();
  }

  let parsed;
  try {
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    sourcesFailed.push(j.source || 'unknown-source');
    continue; // never let malformed AI output reach downstream nodes
  }

  if (parsed && parsed.source && parsed.headline) {
    summaries.push(parsed);
    sourcesSucceeded.push(parsed.source);
  } else {
    sourcesFailed.push(parsed && parsed.source ? parsed.source : (j.source || 'unknown-source'));
  }
}

const successCount = summaries.length;
const totalSources = ALL_SOURCES.length;

return [{
  json: {
    summaries,
    successCount,
    totalSources,
    successLabel: `${successCount}/${totalSources} sources`,
    sourcesSucceeded,
    sourcesFailed
  }
}];

