// FIX APPLIED: normalizes primary/backup output, strips stray fences,
// and records full governance/logging signals for this run.
const input = $input.first().json;
let draft = input.output || input.text || JSON.stringify(input);

if (typeof draft === 'string') {
  draft = draft
    .trim()
    .replace(/^```(?:markdown)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

const upstream = $('Collate Successful Summaries').first().json;

// If this item arrived via the Backup Editor branch, the Chief Editor
// node never produced output on this run -> we used the fallback.
let usedBackup = true;
try {
  $('AI Agent - Chief Editor (Primary: GPT-4o)').first();
  usedBackup = false;
} catch (e) {
  usedBackup = true;
}

const WORKFLOW_LOGIC_VERSION = 'v2.0-resilient';

return [{
  json: {
    date: new Date().toISOString().slice(0, 10),
    runTimestamp: new Date().toISOString(),
    successfulSources: upstream.successLabel,
    sourcesSucceeded: (upstream.sourcesSucceeded || []).join(', '),
    sourcesFailed: (upstream.sourcesFailed || []).join(', ') || 'none',
    draftBody: draft,
    modelUsed: usedBackup ? 'openai/gpt-4o-mini (backup)' : 'openai/gpt-4o (primary)',
    workflowVersion: WORKFLOW_LOGIC_VERSION
  }
}];

// Merge the rendered HTML back onto the same record that already
// has date / successfulSources / modelUsed, so downstream nodes
// have everything in one item.
const draft = $('Normalize Final Draft').first().json;
const html = $json.data ?? $json.html ?? $json;
return [{
  json: {
    ...draft,
    draftBodyHtml: html
  }
}];

const technicalError = (() => {
  const e = $json.error;

  if (!e) return `HTTP ${$json.statusCode ?? 'unknown'}`;

  if (typeof e === 'string') return e;

  if (e.message) return String(e.message);

  try {
    return JSON.stringify(e);
  } catch {
    return String(e);
  }
})();

const raw = technicalError.toLowerCase();

let userFriendlyError;

if (raw.includes('timeout')) {
  userFriendlyError = 'The source took too long to respond.';
} else if (raw.includes('404')) {
  userFriendlyError = 'The page could not be found.';
} else if (raw.includes('403')) {
  userFriendlyError = 'Access to the source was denied.';
} else if (raw.includes('429')) {
  userFriendlyError = 'The source is temporarily limiting requests.';
} else {
  userFriendlyError = 'The source could not be retrieved.';
}

return [{
  json: {
    source: 'TechCabal',
    status: 'fetch_failed',
    error: userFriendlyError,
    headline: null
  }
}];

